union all select 'bld', count(*), count(*) filter (where bdc.m=brc.m), string_agg(case when bdc.m is distinct from brc.m then coalesce(bdc.key,brc.key) end, ',') from bdc full join brc using(key)
union all select 'nbld', (select count(*) from ask_aar_builders where snapshot_id=177), null, null
union all select 'rowmd5 '||(select string_agg(check_code||':'||row_md5,' ') from ask_aar_snapshots_check() where row_id=177), null,null,null
union all select 'codes '||(select coalesce(string_agg(distinct check_code,','),'') from ask_aar_snapshots_check()), null,null,null
union all select 'gc '||g::text, null,null,null from ask_aar_grades_check() g where g.snapshot_id=177;